using System.Web.Script.Services; using System.Web.Services;
namespace WamoApp.Admin { public partial class PaymentsPage : WamoApp.AdminPage { [WebMethod][ScriptMethod(ResponseFormat = ResponseFormat.Json)] public static object GetList() { SessionManager.RequireAuthenticated(); PermissionManager.DemandPermission("Payments", "View"); return AdminDataService.GetList("Payments"); } [WebMethod][ScriptMethod(ResponseFormat = ResponseFormat.Json)] public static object GetDefinition() { SessionManager.RequireAuthenticated(); PermissionManager.DemandPermission("Payments", "View"); return AdminDataService.GetDefinitionMetadata("Payments"); } [WebMethod][ScriptMethod(ResponseFormat = ResponseFormat.Json)] public static object DeleteRecord(string id) { SecurityHelper.ValidateCsrfOrThrow(); SessionManager.RequireAuthenticated(); PermissionManager.DemandPermission("Payments", "Delete"); return AdminDataService.Delete("Payments", id); } } }
